def crc(b):
    return zlib.crc32(b) & 0xFFFFFFFF


def rec(seq, kind, txid, payload=b'', plen=None, crcval=None, raw_hdr=None):
    body = raw_hdr if raw_hdr is not None else struct.pack('<IIBI', len(payload) if plen is None else plen, seq, kind, txid) + payload
    c = crc(body) if crcval is None else crcval
    return body + struct.pack('<I', c)


def patch(pidx, off, data):
    return struct.pack('<HHH', pidx, off, len(data)) + data


